//! 📝️ Native paged receiving observes the neutral Unicode corpus through actual original construction grants.
use super::*;
use crate::{DslValue,retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
pub(super) fn funded(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096.max(d.copy_bytes),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
pub(super) fn drain<T:RetireOwned>(value:T){let mut close=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("paged native fixture closure"));for _ in 0..10000{if close.terminal_is_empty(){return}let d=close.next_demand(4096).unwrap();close.step(funded(d)).unwrap();}panic!("paged native closure stalled")}
fn original(text:&str)->RetainedCloneSource<DslValue>{let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(DslValue::String(text.into()),(),funded(RetirementDemand{copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).unwrap_or_else(|_|panic!("original paged text source")).0}
#[test]fn original_paged_text_admits_exact_unicode_and_closes_every_partial_owner(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let text=row["text"].as_str().unwrap();assert_eq!(text.len(),row["bytes"].as_u64().unwrap()as usize);if row["maximum"]==1{let source=original(text);let(mut receiver,_)=<PagedUtf8<1> as NativeReceive<DslValue>>::begin_receive(funded(<PagedUtf8<1> as NativeReceive<DslValue>>::receive_birth_demand())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let d=receiver.demands(source.borrow(),4096).unwrap();receiver.advance(source.borrow(),&mut control,4096,funded(d)).unwrap();assert!(receiver.demands(source.borrow(),4096).is_err());receiver.begin_close();while !receiver.terminal_is_empty(){let d=receiver.close_demands(4096).unwrap();receiver.close_step(funded(d)).unwrap();}drain(source);continue}for cut in [0,1,4,40,4096]{let source=original(text);let(mut receiver,_)=<PagedUtf8<4096> as NativeReceive<DslValue>>::begin_receive(funded(<PagedUtf8<4096> as NativeReceive<DslValue>>::receive_birth_demand())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);for _ in 0..cut{if receiver.output_ready(){break}let d=receiver.demands(source.borrow(),4096).unwrap();let g=funded(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(source.borrow(),4096).unwrap(),d);}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.advance(source.borrow(),&mut control,4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}if receiver.output_ready(){let(value,_)=receiver.take(funded(receiver.take_demand().unwrap())).unwrap().unwrap();assert_eq!(value.to_string_owner(),text);assert_eq!(value.len(),text.len());drain(value);}receiver.begin_close();while !receiver.terminal_is_empty(){let d=receiver.close_demands(4096).unwrap();receiver.close_step(funded(d)).unwrap();}drain(source);}}}
